/* cu-effects:tiktok — emergency/alert, high-visibility, not luxury glass. No marks, no proprietary fonts. */

:root {
  font-family: var(--cu-font-family-sans, system-ui, sans-serif);
  letter-spacing: var(--cu-font-tracking-wide, 0.08em);
  font-weight: 700;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

:root .cu-button,
:root .cu-badge,
:root .cu-input,
:root .cu-select__trigger,
:root .cu-sheet__close,
:root .cu-navbar__item,
:root .cu-checkbox__control {
  border-radius: var(--cu-radius-md);
  box-shadow: var(--cu-shadow-sm);
  transition-duration: var(--cu-motion-duration-base);
  transition-timing-function: var(--cu-motion-easing-standard);
}

:root .cu-button,
:root .cu-badge {
  text-transform: uppercase;
  font-weight: 800;
  letter-spacing: var(--cu-font-tracking-wide, 0.08em);
  border: 2px solid var(--cu-color-border-default);
}

:root .cu-button--solid,
:root .cu-badge--primary {
  color: var(--cu-color-fg-default);
  background: var(--cu-color-palette-brand);
}

:root .cu-card,
:root .cu-alert,
:root .cu-toast,
:root .cu-sheet,
:root .cu-dialog__content,
:root .cu-action-sheet__content,
:root .cu-command-palette__content {
  border-radius: var(--cu-radius-md);
  box-shadow: none;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  background-color: var(--cu-color-background-elevated, var(--cu-color-background-default));
  border: 2px solid var(--cu-color-border-default);
}

:root .cu-alert,
:root .cu-toast {
  background: var(--cu-color-background-subtle);
  border-inline-start-width: 10px;
  border-inline-start-color: var(--cu-color-fg-default);
}

:root .cu-input,
:root .cu-select__trigger {
  border: 2px solid var(--cu-color-border-default);
  background: var(--cu-color-background-elevated, var(--cu-color-background-default));
}

:root .cu-dialog__backdrop,
:root .cu-action-sheet__backdrop,
:root .cu-sheet__backdrop,
:root .cu-command-palette__backdrop {
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  background: color-mix(in srgb, var(--cu-color-background-inverse) 78%, transparent);
}

:root .cu-app-shell__header,
:root .cu-navbar {
  position: relative;
  background: var(--cu-color-palette-brand);
  color: var(--cu-color-fg-default);
  border-block-end: 0;
  padding-block-end: calc(var(--cu-space-2) + 8px);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  box-shadow: none;
}

:root .cu-app-shell__header::after,
:root .cu-navbar::after {
  content: '';
  position: absolute;
  inset-inline: 0;
  inset-block-end: 0;
  block-size: 8px;
  background: repeating-linear-gradient(
    -45deg,
    #171717 0 8px,
    var(--cu-color-palette-brand) 8px 16px
  );
}

:root .cu-app-shell__header .cu-heading,
:root .cu-app-shell__header .cu-typography,
:root .cu-app-shell__header .cu-demo-kicker,
:root .cu-navbar .cu-heading,
:root .cu-navbar .cu-typography {
  color: var(--cu-color-fg-default);
  font-weight: 800;
  text-transform: uppercase;
}

:root .cu-tab-bar {
  background: var(--cu-color-palette-brand);
  color: var(--cu-color-fg-default);
  border-block-start: 8px solid #171717;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  box-shadow: none;
}

:root .cu-tab-bar__item[data-state='active'] {
  color: var(--cu-color-fg-default);
  background: var(--cu-color-background-subtle);
  border-block-start-color: #171717;
  font-weight: 800;
}

:root .cu-sidebar {
  background: var(--cu-color-background-subtle);
  border-inline-end: 2px solid var(--cu-color-border-default);
}

:root .cu-heading,
:root .cu-typography--heading-1,
:root .cu-typography--heading-2 {
  font-weight: 800;
  letter-spacing: var(--cu-font-tracking-wide, 0.08em);
}

@media (prefers-reduced-motion: reduce) {
  :root .cu-button,
  :root .cu-badge,
  :root .cu-input,
  :root .cu-select__trigger,
  :root .cu-dialog__content,
  :root .cu-action-sheet__content {
    transition-duration: 0.01ms;
  }
}
